<?php
declare(strict_types=1);require dirname(__DIR__).'/private/app/bootstrap.php';$pdo=db();$pdo->beginTransaction();try{$roles=[['system_admin','مدیر سیستم'],['company_admin','مدیر شرکت'],['trade_manager','مدیر بازرگانی'],['trade_operator','کارشناس بازرگانی'],['viewer','مشاهده‌گر']];$st=$pdo->prepare('INSERT IGNORE INTO roles(code,name,is_system_role,created_at,updated_at) VALUES(?,?,1,NOW(),NOW())');foreach($roles as$r)$st->execute($r);$modules=['dashboard','opportunities','products','companies','contacts','tasks','prices','quotations','transport','insurance','documents','reports','settings','users','audit'];$ops=['view','create','edit','archive','delete','approve','export','manage_settings'];$st=$pdo->prepare('INSERT IGNORE INTO permissions(code,name,module,created_at) VALUES(?,?,?,NOW())');foreach($modules as$m)foreach($ops as$o)$st->execute(["$m.$o","$m: $o",$m]);$adminRole=(int)$pdo->query("SELECT id FROM roles WHERE code='system_admin'")->fetchColumn();$pdo->exec("INSERT IGNORE INTO permission_role(role_id,permission_id) SELECT $adminRole,id FROM permissions");foreach(['viewer'=>['view'],'trade_operator'=>['view','create','edit'],'trade_manager'=>['view','create','edit','archive','approve','export']]as$role=>$allowed){$rid=(int)$pdo->query("SELECT id FROM roles WHERE code=".$pdo->quote($role))->fetchColumn();foreach($allowed as$op)$pdo->exec("INSERT IGNORE INTO permission_role(role_id,permission_id) SELECT $rid,id FROM permissions WHERE code LIKE '%.$op'");}$password=getenv('ADMIN_PASSWORD')?:bin2hex(random_bytes(8));$email=getenv('ADMIN_EMAIL')?:'admin@localhost';$st=$pdo->prepare("INSERT INTO users(name,email,username,password,status,created_at,updated_at) VALUES('مدیر سیستم',?,'admin',?,'active',NOW(),NOW()) ON DUPLICATE KEY UPDATE updated_at=updated_at");$st->execute([$email,password_hash($password,PASSWORD_ARGON2ID)]);$uid=(int)$pdo->query("SELECT id FROM users WHERE username='admin'")->fetchColumn();$st=$pdo->prepare('INSERT IGNORE INTO role_user(user_id,role_id) VALUES(?,?)');$st->execute([$uid,$adminRole]);$stages=['initial_review'=>'بررسی اولیه','information_gathering'=>'تکمیل اطلاعات','sourcing'=>'تأمین‌یابی','quotation'=>'استعلام و پیشنهاد','negotiation'=>'مذاکره','documents'=>'اسناد','payment'=>'پرداخت','logistics'=>'لجستیک','completed'=>'تکمیل','cancelled'=>'لغو'];$st=$pdo->prepare('INSERT IGNORE INTO opportunity_stages(code,name,sort_order,is_terminal,is_active,created_at,updated_at) VALUES(?,?,?,?,1,NOW(),NOW())');$i=10;foreach($stages as$c=>$n){$st->execute([$c,$n,$i,in_array($c,['completed','cancelled'])?1:0]);$i+=10;}foreach([['IR','IRN','ایران','Iran'],['CN','CHN','چین','China'],['AE','ARE','امارات متحده عربی','UAE'],['TR','TUR','ترکیه','Turkey']]as$x){$st=$pdo->prepare('INSERT IGNORE INTO countries(iso2,iso3,name_fa,name_en,is_active,created_at,updated_at) VALUES(?,?,?,?,1,NOW(),NOW())');$st->execute($x);}foreach([['IRR','ریال','Iranian Rial','﷼',0],['USD','دلار آمریکا','US Dollar','$',2],['EUR','یورو','Euro','€',2],['AED','درهم امارات','UAE Dirham','د.إ',2]]as$x){$st=$pdo->prepare('INSERT IGNORE INTO currencies(code,name_fa,name_en,symbol,decimal_places,is_active,created_at,updated_at) VALUES(?,?,?,?,?,1,NOW(),NOW())');$st->execute($x);}foreach([['kg','کیلوگرم','Kilogram','mass'],['ton','تن','Tonne','mass'],['pcs','عدد','Piece','count'],['ltr','لیتر','Litre','volume']]as$x){$st=$pdo->prepare('INSERT IGNORE INTO units(code,name_fa,name_en,dimension,is_active,created_at,updated_at) VALUES(?,?,?,?,1,NOW(),NOW())');$st->execute($x);}foreach([['road','جاده‌ای','Road'],['sea','دریایی','Sea'],['air','هوایی','Air'],['rail','ریلی','Rail']]as$x){$st=$pdo->prepare('INSERT IGNORE INTO transport_methods(code,name_fa,name_en,is_active,created_at,updated_at) VALUES(?,?,?,1,NOW(),NOW())');$st->execute($x);}$pdo->exec("INSERT INTO company_settings(setting_key,setting_value,updated_at) VALUES('company_name_fa','شرکت بازرگانی',NOW()),('company_name_en','Trade Company',NOW()),('timezone','Asia/Tehran',NOW()),('opportunity_prefix','OPP',NOW()),('document_prefix','DOC',NOW()) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)");$pdo->commit();echo"Seed completed.\n";}catch(Throwable$e){$pdo->rollBack();throw$e;}
